/usr/bin/zsh -lc "python3 -c 'import os,hashlib,json; p=os.path.realpath(\"index.ts\"); h=lambda:hashlib.sha256(open(p,\"rb\").read()).hexdigest(); before=h(); result={\"path\":p,\"hash_before\":before};
try:
 fd=os.open(p,os.O_WRONLY); os.close(fd); result.update(open_succeeded=True,errno=None)
except OSError as e:
 result.update(open_succeeded=False,errno=e.errno,error=str(e))
mounts=[]
for line in open(\"/proc/self/mountinfo\"):
 fields=line.split(); m=fields[4].replace(\"\\\\040\",\" \");
 if p==m or p.startswith(m.rstrip(\"/\")+\"/\"): mounts.append((len(m),line.strip()))
result[\"covering_mount\"]=max(mounts)[1] if mounts else None; result[\"hash_after\"]=h(); result[\"unchanged_hash\"]=before==result[\"hash_after\"]; print(json.dumps(result))'"

